library(readr)
library(dplyr)
library(haven)

# Load the datasets
wave1 <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t")
wave4 <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t")
wave8 <- read_delim("data/input/ns8_2015_derived.tab", delim = "\t")
wave9 <- read_delim("data/input/ns9_2022_derived_variables.tab", delim = "\t")

# Merge datasets using full_join by NSID
merged_data <- wave1 %>%
  full_join(wave4, by = "NSID") %>%
  full_join(wave8, by = "NSID") %>%
  full_join(wave9, by = "NSID")

# Function to apply standard missing value codes
apply_missing_codes <- function(x) {
  if (is.na(x)) {
    return(-3)
  } else if (x < 0) {
    if (x == -9) {
      return(-9)
    } else if (x == -8) {
      return(-8)
    } else if (x == -1) {
      return(-1)
    } else {
      return(-2)
    }
  } else {
    return(x)
  }
}

# Derive bmi25 from W8DBMI (Wave 8, Age 25)
merged_data <- merged_data %>%
  mutate(bmi25 = apply_missing_codes(W8DBMI))

# Derive bmi32 from W9DBMI (Wave 9, Age 32)
merged_data <- merged_data %>%
  mutate(bmi32 = apply_missing_codes(W9DBMI))

# Select only the ID variable and the derived BMI variables
final_data <- merged_data %>%
  select(NSID, bmi25, bmi32)

# Write the output CSV
write_csv(final_data, "data/output/cleaned_data.csv")

